result=template.replace('__BANK__',json.dumps(bank,ensure_ascii=False).replace('</','<\\/')).replace('__ENGINE__',(ROOT/'tasks.js').read_text()).replace('__APP__',(ROOT/'app.js').read_text())
(ROOT/'index.html').write_text(result)
